#!/usr/bin/env bash
# Regenerate crates/gui/src/slint_generated.rs from ui/*.slint.
#
# Normal dev machines just build with the default `slint-compile` feature and
# never need this script. It exists for memory-starved CI boxes (~1 GB RAM)
# where compiling i-slint-compiler can get OOM-killed: those build with
# `--no-default-features` and rely on the checked-in generated file instead.
#
# Requires a machine with enough RAM to compile i-slint-compiler (~2 GB).
# Slint is pinned to 1.6.0; regenerate with the same version to avoid churn.
set -euo pipefail
cd "$(dirname "$0")/.."

cargo build -p udm-gui --features slint-compile

OUT=$(find target -path '*build/udm-gui-*/out/app.rs' -newer crates/gui/ui/app.slint | head -1)
if [ -z "$OUT" ]; then
    echo "could not locate generated app.rs under target/*/build/udm-gui-*/out/" >&2
    exit 1
fi

{
    echo "// Generated by slint-build 1.6.0 from ui/app.slint - DO NOT EDIT."
    echo "// Regenerate with packaging/regenerate-slint.sh (used when building with"
    echo "// --no-default-features, i.e. without running the .slint compiler)."
    cat "$OUT"
} > crates/gui/src/slint_generated.rs
echo "regenerated crates/gui/src/slint_generated.rs from $OUT"
